import test from 'node:test';import assert from 'node:assert/strict';
import {FactoryGame} from '../ascent-model.js';import {STEP} from '../game-model.js';
import {floorBase,gateY,gateHeight,makeRoom,roomGeometry,roomCookies,hitsRoom,AscentDirector} from '../ascent-world.js';
import {readFileSync} from 'node:fs';
// Generated by findAscentWitness; replay always uses the unmodified production model.
const witnesses=JSON.parse(readFileSync(new URL('./fixtures/ascent-inputs.json',import.meta.url)));
const start=(floor=1,options={})=>{const g=new FactoryGame({mode:'ascent',seed:42,profile:{ascentUnlocked:[1,2,3],ascentStart:floor},...options});g.press();return g;};
test('one-button physics and monotone camera remain; pause freezes all room clocks',()=>{
 const g=start();g.update();assert.equal(g.bird.x,178);assert.equal(g.bird.y,283);assert.equal(g.bird.vy,-7.5);
 for(let i=0;i<20;i++){g.press();g.update();}assert.equal(g.bird.y+29-g.cameraTop,256);
 const top=g.cameraTop;g.bird.vy=4;g.update();assert.equal(g.cameraTop,top);
 g.paused=true;const before=JSON.stringify([g.bird,g.courseTime,g.director.rooms]);g.press();g.update();assert.equal(JSON.stringify([g.bird,g.courseTime,g.director.rooms]),before);
});
test('rooms activate once, use fixed coordinates, and preserve their phase after retreat',()=>{
 const g=start();g.director.ensure(g);const r=g.director.rooms[0],time=r.activatedAt;
 g.maxHeight=800;g.courseTime=4;g.director.ensure(g);g.maxHeight=100;g.courseTime=5;g.director.ensure(g);
 assert.equal(r.activatedAt,time);assert.equal(r.start,0);assert.equal(g.director.rooms[1].activatedAt,4);
 const preview=roomGeometry(r,2);g.cameraTop=-500;assert.deepEqual(roomGeometry(r,2),preview);
});
test('solid machinery kills through frenzy and swept contact catches a crossed shutter',()=>{
 const g=start(2),r=g.director.rooms[0];r.activatedAt=0;
 const y=320-r.start-340,hit=hitsRoom(r,{x:200,y:y+100},{x:200,y:y-100},2,STEP);assert.equal(hit.kind,'shutter');
 g.courseTime=2;g.abilityRemaining=3;g.bird.x=172;g.bird.y=y+24-29;g.bird.vy=-8;g.cameraTop=y-240;
 g.update();assert.equal(g.state,'dying');assert.equal(g.cause,'structure');
});
test('each room has a second of preparation and identical geometry after retry',()=>{
 for(const floor of [1,2,3]){const a=start(floor),b=start(floor);a.director.ensure(a);b.director.ensure(b);
  for(const r of a.director.rooms.filter(r=>r.floor===floor)){
   r.activatedAt=0;assert.equal(roomGeometry(r,.99).warning,true);assert.equal(roomGeometry(r,1.01).warning,false);
   const other=b.director.rooms.find(s=>s.id===r.id);other.activatedAt=0;assert.deepEqual(roomGeometry(r,2.4),roomGeometry(other,2.4));
  }
 }
});
test('ordinary and golden cookies coexist, stay physical, and golden adds two charges',()=>{
 const g=start();assert.ok(g.cookies.length>1);const gold=g.cookies.find(c=>c.golden);g.cookie=gold;g.collectCookie();assert.equal(g.energy,2);assert.equal(g.metrics.goldenCookies,1);assert.ok(!g.cookies.includes(gold));
 const plain=g.cookies.find(c=>!c.golden);g.cookie=plain;g.collectCookie();assert.equal(g.energy,3);
 const c=g.cookies[0];const position={x:c.x,baseY:c.baseY};for(let i=0;i<5;i++)g.update();assert.deepEqual({x:c.x,baseY:c.baseY},position);
});
test('a core requires frenzy and exposure, saves the next floor once, and preserves visible pickups',()=>{
 const discoveries=[],g=start(2,{onDiscover:f=>discoveries.push(f)});g.director.ensure(g);const r=g.director.rooms.find(r=>r.boss&&r.floor===2);r.activatedAt=0;g.courseTime=.5;
 assert.equal(g.breakMachine(),false);g.abilityRemaining=3;assert.equal(g.breakMachine(),false);g.courseTime=2;
 const cookies=[...g.cookies];assert.equal(g.breakMachine(),true);assert.deepEqual(discoveries,[3]);assert.equal(g.breakMachine(),false);assert.deepEqual(g.cookies,cookies);assert.ok(g.hitstop>0);
});
test('the feeder replenishes missed cookies only offscreen and falls remain lethal',()=>{
 const g=start();g.maxHeight=gateHeight(1)-30;g.cameraTop=-g.maxHeight+64;g.spawnCookie();const c=g.cookies.find(c=>c.feeder);assert.ok(c);
 g.spawnCookie();assert.equal(g.cookies.find(p=>p.feeder),c);g.cookie=c;g.collectCookie();assert.ok(g.cookies.some(p=>p.feeder&&p!==c));
 g.bird.y=g.cameraTop+710;g.bird.vy=1;g.update();assert.equal(g.cause,'fall');
});
test('fixed and variable button spam cannot traverse the first three rooms on any floor',()=>{
 for(const floor of [1,2,3])for(let pattern=0;pattern<70;pattern++){
  const g=start(floor);let state=pattern+1;g.abilityRemaining=pattern%2?3:0;
  for(let frame=0;frame<1800&&g.state==='playing';frame++){
   state=(Math.imul(state,1664525)+1013904223)>>>0;
   const period=[1,2,5,8,10,12,15,20,30][pattern%9];
   if(pattern<9?frame%period===0:state/2**32<(.08+(pattern%12)*.07))g.press();g.update();
  }
  assert.notEqual(g.state,'playing',`floor ${floor}, pattern ${pattern}`);assert.ok(g.maxHeight<floorBase(floor)+1440,`blind pattern crossed rooms: floor ${floor}, pattern ${pattern}`);
 }
});
test('endless rooms retain a bounded active world and mirror known patterns without speed escalation',()=>{
 const director=new AscentDirector(3),g={maxHeight:5760,cameraTop:-5700,startFloor:3,courseTime:20,balls:[]};director.ensure(g);assert.ok(director.rooms.some(r=>r.mirror));
 for(let n=1;n<100;n++){g.maxHeight=5760+n*1440;g.cameraTop=-g.maxHeight+64;g.courseTime+=10;director.ensure(g);assert.ok(director.rooms.length<=7);}
 const r=makeRoom(1,0,1);r.activatedAt=0;assert.equal(roomGeometry(r,2).shapes[0].x,140);
});
for(const floor of [1,2,3])test(`real input replay passes floor ${floor}, its machine and transition`,()=>{
 const inputs=witnesses[floor].full,discovered=[],g=start(floor,{onDiscover:f=>discovered.push(f)});let top=g.cameraTop;
 for(const input of inputs){if(input)g.press();g.update();assert.equal(g.state,'playing');assert.ok(g.cameraTop<=top);top=g.cameraTop;}
 assert.ok(g.machines[floor-1].broken);assert.ok(g.maxHeight>=gateHeight(floor)+90);assert.equal(g.floor,floor+1);
 assert.ok(g.collected>=3);assert.ok(g.metrics.abilities>0);assert.deepEqual(discovered,floor<3?[floor+1]:[]);
});

for(const floor of [1,2,3])test(`all ordinary rooms on floor ${floor} are reachable without activating frenzy`,()=>{
 const g=start(floor);for(const input of witnesses[floor].rooms){if(input)g.press();g.update();assert.equal(g.state,'playing');assert.equal(g.abilityRemaining,0);}
 assert.ok(g.maxHeight>=floorBase(floor)+1440);
});

for(const floor of [1,2,3])for(let room=0;room<3;room++)test(`optional golden cookie is reachable on floor ${floor}, room ${room+1}`,()=>{
 const g=start(floor),id=`${floor}:${room}:gold`;assert.ok(g.cookies.some(c=>c.id===id));
 for(const input of witnesses[floor].gold[room]){if(input)g.press();g.update();assert.equal(g.state,'playing');}
 assert.ok(!g.cookies.some(c=>c.id===id));assert.ok(g.metrics.goldenCookies>0);assert.ok(g.maxHeight<floorBase(floor)+room*480+910,'cookie was collected rather than discarded offscreen');
});
test('the following floor waits for its unlock transition instead of cycling unseen during the boss',()=>{
 const g=start();g.maxHeight=1770;g.courseTime=20;g.director.ensure(g);
 assert.equal(g.director.rooms.find(r=>r.floor===2).activatedAt,null);
 g.floor=2;g.courseTime=21;g.director.ensure(g);assert.equal(g.director.rooms.find(r=>r.floor===2).activatedAt,21);
});

test('mirrored endless layouts reflect rewards, machines and pendulum paths together',()=>{
 for(const floor of [1,2,3])for(let index=0;index<3;index++){
  const room=makeRoom(floor,index,1);room.activatedAt=0;const normal={...room,mirror:false};
  const a=roomCookies(room),b=roomCookies(normal);for(let i=0;i<a.length;i++)assert.equal(a[i].x,370-b[i].x);
  const left=roomGeometry(room,2).shapes,right=roomGeometry(normal,2).shapes;assert.equal(left.length,right.length);
  for(let i=0;i<left.length;i++)assert.ok(Math.abs(left[i].x-(400-right[i].x-(right[i].w||0)))<1e-7);
 }
});
